// ================= Ten Thousand Buddhas Monastery, Sha Tin (founded 1949 by Rev. Yuet Kai, completed 1957) =================
// Lower level: the main temple (the Ten Thousand Buddhas Hall, "red and gold"), the courtyard with the pavilions (Kwun Yam in the
// centre) and the arhat galleries, and the red / pink nine-storey pagoda "at the opposite end of the Main Hall" (HK Memory: nine
// storeys, hexagonal plan, the "Pink Pagoda"; kiranabhat.com); the upper level's halls; the 431-step access path lined with the
// 500 golden arhat statues (droneandslr.com). Footprints: OSM (main hall w329019991, galleries w435018859 / w435018860, Kwun Yam
// pavilion w1187508633, the Samantabhadra / Manjusri pavilions w1187516146 / w1187516147, the upper halls w435014763-5, w1187505210-3);
// the pagoda is not in OSM: it stands on the untagged w1187862803 at the courtyard's far end. Heights are estimates (pagoda ~30 m).
// Every building stands on its own plinth on the app's (smoothed) hillside: the monastery steps down the slope.
const TB = D.tb;
const SB = {red:{c:'#b3322b', m:0, lc:'#ffcf9a', lk:0.55}, gold:{c:'#d6a43a', m:0, lc:'#ffd9a0', lk:0.6}, roof:{c:'#d4a23b', m:0, lc:'#ffcf8a', lk:0.35},
  ridge:'#b77f26', cream:{c:'#eadfc6', m:0, lc:'#ffd9a8', lk:0.45}, pink:{c:'#e3a3a6', m:0, lc:'#ffd2b0', lk:0.85, e:0.7}, plat:'#b3ab9b', step:'#a9a397',
  pave:'#c8c0ae', col:'#a92b24', lan:{c:'#d84b2a', glow:'#ffb060', gk:1.5}, stat:{c:'#d0a033', m:0, lc:'#ffdca0', lk:0.4}, ped:'#9d988e', win:{c:'#4a3a2e', glow:'#ffc77a', gk:0.7}, green:'#4f6e3e'};
function tbBase(key){ const K = TB[key], def = LANDMARKS[key]; return baseOf(K.lat, K.lon, def.r); }
// plinth under a ring: top = highest ground + 0.4 (or given), down below the lowest ground
// (the uphill side is cut into the slope: top at 60 % of the ground's fall across the footprint, as terraces are)
function plinth(B, spec, P, gl, extra){ let hi = -Infinity, lo = Infinity; for (const p of P){ const h = gl(p[0], p[1]); hi = Math.max(hi, h); lo = Math.min(lo, h); }
  const c = centroid(P), hc = gl(c[0], c[1]); hi = Math.max(hi, hc); lo = Math.min(lo, hc); const top = lo + 0.6*(hi - lo) + (extra || 0.4); if (B.g) polyH(B.g, P, [], lo - 1.5, top - lo + 1.5, spec); else prism(B, spec, P, lo - 1.5, top); return top; }
