  obox(B, SB.ped, x, z, ux, uz, 0.9, 0.9, y - 0.5, y + 0.7);
  const st = i % 3 !== 0, hb = st ? 1.25 : 0.85, wb = st ? 0.55 : 0.8;
  obox(B, SB.stat, x, z, ux, uz, wb, wb*0.8, y + 0.7, y + 0.7 + hb);
