    for (let k = 0; k < 6; k++){ const a = PI/6 + (k + 0.5)/6*TAU, rr = r*Math.cos(PI/6) + 0.05;  // an arched opening on every face
      obox(B, SB.win, cx + Math.cos(a)*rr, cz + Math.sin(a)*rr, -Math.sin(a), Math.cos(a), r*0.36, 0.12, y + h*0.22, y + h*0.78, true); }
    obox(B, SB.red, cx, cz, 1, 0, 0.1, 0.1, y + h - 0.6, y + h - 0.5, true);
    y += h;
    ringEave(B, SB.roof, 6, PI/6, cx, cz, r - 0.4, r + 1.45, y + 0.85, y - 0.35, 0.55);
