// the access path: two rows of golden arhats every ~1.25 m (500 in all on the two keys)
function tbPath(key){ return function(){
  const g = new THREE.Group(), B = Batch(), bs = tbBase(key), gl = bs.gl, P = TB[key].path;
  let L = 0; for (let i = 0; i < P.length - 1; i++) L += Math.hypot(P[i + 1][0] - P[i][0], P[i + 1][1] - P[i][1]);
  const step = TB.pathStep, n = Math.floor(L/step);
  let k = 0, acc = 0, seg = 0, segL = Math.hypot(P[1][0] - P[0][0], P[1][1] - P[0][1]);
  for (let i = 0; i <= n; i++){ const s = i*step;
    while (seg < P.length - 2 && s > acc + segL){ acc += segL; seg++; segL = Math.hypot(P[seg + 1][0] - P[seg][0], P[seg + 1][1] - P[seg][1]); }
    const t = clamp((s - acc)/(segL || 1), 0, 1), a = P[seg], b = P[seg + 1], x = lerp(a[0], b[0], t), z = lerp(a[1], b[1], t), dx = (b[0] - a[0])/(segL || 1), dz = (b[1] - a[1])/(segL || 1);
    for (const sd of [-1, 1]){ const qx = x - dz*sd*2.3, qz = z + dx*sd*2.3; k++;
      if ((TB[key].avoid || []).some(R => pip(R, qx, qz) || ringNear(R, qx, qz)[0] < 1.0)) continue;   // not inside the houses by the path
      arhat(B, qx, gl(qx, qz), qz, Math.atan2(dz, dx), k); } }
  B.flush(g); return g; }; }
{
  let L = 0; for (const k of ['hk10kbuddhas_c', 'hk10kbuddhas_d']){ const P = TB[k].path; for (let i = 0; i < P.length - 1; i++) L += Math.hypot(P[i + 1][0] - P[i][0], P[i + 1][1] - P[i][1]); }
  TB.pathStep = L/250;
  for (const k of ['hk10kbuddhas_c', 'hk10kbuddhas_d']){ let r = 0; for (const p of TB[k].path) r = Math.max(r, Math.hypot(p[0], p[1]));
    LANDMARKS[k] = {zh:'万佛寺', en:'Ten Thousand Buddhas Monastery (Sha Tin)', cat:'old', r:Math.ceil(r + 6), h:4, label:false, lt:{m:0, c:'#ffcf9a', k:0.4}, build:tbPath(k)}; }
  for (const k of ['hk10kbuddhas', 'hk10kbuddhas_b', 'hk10kbuddhas_c', 'hk10kbuddhas_d']) SG_PLACES.push({type:k, lat:TB[k].lat, lon:TB[k].lon, rot:0});
}

// extruded plan polygon with holes (concave allowed): walls + top / bottom caps
function polyH(g, outer, holes, y0, h, col){
  const sh = new THREE.Shape(outer.map(p => new THREE.Vector2(p[0], -p[1])));
  for (const H of holes || []) sh.holes.push(new THREE.Path(H.map(p => new THREE.Vector2(p[0], -p[1]))));
  const geo = new THREE.ExtrudeGeometry(sh, {depth:h, bevelEnabled:false}), m = lmAdd(g, geo, col, 0, y0, 0); m.rotation.x = -HP; return m;
}
// a "hipped" roof over any plan (holes allowed): height grows with the distance to the nearest edge (pitch), capped at hmax;
// grid of cell s, vertices outside snapped to the eave line
function skelRoof(B, spec, outer, holes, y0, pitch, hmax, s, over){
  const O = over ? grow(outer, over) : outer, Hs = (holes || []).map(H => over ? grow(H, -over) : H);
  let x0 = Infinity, x1 = -Infinity, z0 = Infinity, z1 = -Infinity; for (const p of O){ x0 = Math.min(x0, p[0]); x1 = Math.max(x1, p[0]); z0 = Math.min(z0, p[1]); z1 = Math.max(z1, p[1]); }
  x0 -= s; z0 -= s; const nx = Math.ceil((x1 - x0)/s) + 2, nz = Math.ceil((z1 - z0)/s) + 2, V = new Array(nx*nz), IN = new Uint8Array(nx*nz);
  for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++){ const x = x0 + i*s, z = z0 + j*s, k = j*nx + i;
    const inH = Hs.findIndex(H => pip(H, x, z));
    if (!pip(O, x, z)){ const [, bx, bz] = ringNear(O, x, z); V[k] = [bx, y0, bz]; continue; }
    if (inH >= 0){ const [, bx, bz] = ringNear(Hs[inH], x, z); V[k] = [bx, y0, bz]; continue; }
    let d = ringNear(O, x, z)[0]; for (const H of Hs) d = Math.min(d, ringNear(H, x, z)[0]);
    V[k] = [x, y0 + Math.min(hmax, d*pitch), z]; IN[k] = 1; }
  for (let j = 0; j < nz - 1; j++) for (let i = 0; i < nx - 1; i++){ const a = j*nx + i, b = a + 1, c = a + nx + 1, d = a + nx;
    if (IN[a] + IN[b] + IN[c] + IN[d] === 0) continue; B.q(spec, V[a], V[b], V[c], V[d]); }
}
// ================= Che Kung Temple, Tai Wai (the 1993-94 temple in front of the old one) =================
