    for (let k = 0; k < 6; k++){ const a = rot + (k + 0.5)/6*TAU, rr = r*Math.cos(PI/6) + 0.03; if ((k + s) % 2) continue;
      obox(B, win, c[0] + Math.cos(a)*rr, c[1] + Math.sin(a)*rr, -Math.sin(a), Math.cos(a), 0.9, 0.08, y + h*0.35, y + h*0.75, true); }
